export type RequestOtpData = {
    /**
     * The channel to deliver the code through, the identifier to send it to and the surface it signs in to.
     */
    body: OtpRequest;
    path?: never;
    query?: never;
    url: '/v1/auth/otp/request';
};

export type RequestOtpErrors = {
    /**
     * The body failed validation (`validation_failed`), for example an identifier that is not an email address or an E.164 phone number for the channel, `audience_required` on `/audience` without a surface, or `audience_not_allowed` on `/audience` for Mission Control. The `errors` member points at the offending field.
     */
    400: Problem;
    /**
     * The phone number's country is not accepting sign-in (`sign_in_closed`); a number from no known country is refused too.
     */
    409: Problem;
    /**
     * Too many codes were requested for this identifier or from this client (`too_many_requests`). The `Retry-After` header says how many seconds to wait.
     */
    429: Problem;
    /**
     * Another client error, such as `415` for a body that is not JSON, returned as an RFC 9457 problem details document.
     */
    '4XX': Problem;
    /**
     * An unexpected server error, returned as an RFC 9457 problem details document.
     */
    default: Problem;
};

export type RequestOtpError = RequestOtpErrors[keyof RequestOtpErrors];

export type RequestOtpResponses = {
    /**
     * The code is being delivered. The body identifies the challenge to verify the code against.
     */
    202: OtpChallenge;
};

export type RequestOtpResponse = RequestOtpResponses[keyof RequestOtpResponses];

export type VerifyOtpData = {
    /**
     * The challenge from `POST /v1/auth/otp/request`, the code that was delivered for it, the surface and the delivery.
     */
    body: OtpVerifyRequest;
    path?: never;
    query?: never;
    url: '/v1/auth/otp/verify';
};

export type VerifyOtpErrors = {
    /**
     * The body failed validation (`validation_failed`), for example a `challenge_id` that is not a UUID, a code that is not six digits, `audience_required` on `/audience` and `delivery_required` on `/delivery` when either is missing, or `audience_not_allowed` on `/audience`.
     */
    400: Problem;
    /**
     * The code was not accepted (`invalid_code` when it does not match the challenge, `code_expired` when the challenge is unknown, used or past `expires_at`), or a right code asked for the Agent app by somebody who is not an agent (`authentication_failed`).
     */
    401: Problem;
    /**
     * The challenge is locked after too many wrong codes (`too_many_attempts`), or the sign-in throttle holds the identifier or the client (`too_many_requests`, with `Retry-After`).
     */
    429: Problem;
    /**
     * Another client error, such as `415` for a body that is not JSON or `429` when rate limited, returned as an RFC 9457 problem details document.
     */
    '4XX': Problem;
    /**
     * An unexpected server error, returned as an RFC 9457 problem details document.
     */
    default: Problem;
};

export type VerifyOtpError = VerifyOtpErrors[keyof VerifyOtpErrors];

export type VerifyOtpResponses = {
    /**
     * The code was accepted and a session was created.
     */
    200: TokenResponse;
    /**
     * The credential was right and the account has two-step sign-in on. No session exists yet; send an authenticator or recovery code with the `challenge_id` to `POST /v1/auth/two-step/verify`.
     */
    202: TwoStepChallenge;
};

export type VerifyOtpResponse = VerifyOtpResponses[keyof VerifyOtpResponses];

